window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"waTVUY2hVU8","speaker":"Rob Jetten","role":"Prime Minister","country":"Netherlands","region":"Europe","url":"https://www.youtube.com/watch?v=waTVUY2hVU8","date":"20260924","title":"🇳🇱 Netherlands - Prime Minister Addresses United Nations General Debate, 81st Session | #UNGA","seconds":855,"words":1977,"counts":{"claims":25,"promises":1,"attacks":1},"topics":[{"topic":"WWII history","share":0.17,"seconds":145},{"topic":"UN reform","share":0.0876,"seconds":75},{"topic":"International justice","share":0.0783,"seconds":67},{"topic":"UN leadership","share":0.0776,"seconds":66},{"topic":"International law","share":0.0763,"seconds":65},{"topic":"AI governance","share":0.076,"seconds":65},{"topic":"Climate agriculture","share":0.0758,"seconds":65},{"topic":"Energy transition","share":0.0729,"seconds":62},{"topic":"Climate change","share":0.0722,"seconds":62},{"topic":"Ukraine war","share":0.0721,"seconds":62},{"topic":"Climate action","share":0.071,"seconds":61},{"topic":"Middle East conflict","share":0.0701,"seconds":60}],"timeline":[[2,73,"WWII history"],[74,134,"Middle East conflict"],[135,201,"International law"],[202,277,"UN reform"],[278,345,"International justice"],[356,418,"Ukraine war"],[419,484,"AI governance"],[485,547,"Climate change"],[548,610,"Energy transition"],[611,672,"Climate action"],[673,738,"Climate agriculture"],[739,805,"UN leadership"],[806,881,"WWII history"],[882,907,null]],"stances":{"WWII history":"Rob Jetten highlights Anne Frank's belief in the power of people to improve the world and quotes her words as being relevant today.","Middle East conflict":"Rob Jetten states that the international legal order is under pressure and highlights unending human suffering in Gaza and Sudan.","International law":"Rob Jetten argues that violations of international law and human rights are fueled by self-interested actors and that a defensive response based on retaliation is counterproductive.","UN reform":"Rob Jetten argues that the UN Security Council requires improved African representation and a shift in the balance of power to reflect modern times.","International justice":"Rob Jetten argues that undermining the International Criminal Court weakens the entire international legal order and calls for protecting it from such attacks.","Ukraine war":"Rob Jetten asserts that impunity must be fought through a special tribunal for the crime of aggression against Ukraine, which the Netherlands has offered to host, and emphasizes that Russia must be held accountable for its violations of the UN charter.","AI governance":"Rob Jetten advocates for collective decision-making on AI within the United Nations rather than allowing a small group of companies and countries to dominate.","Climate change":"Rob Jetten states that the climate crisis is accelerating, particularly in Western Europe and the Caribbean, and argues that immediate commitment to mitigation and adaptation is necessary to prevent future generations from paying the price.","Energy transition":"Rob Jetten states that the Netherlands and Colombia organized a conference to accelerate the transition away from fossil fuels and reduce carbon emissions.","Climate action":"Rob Jetten argues that climate action is achievable through existing knowledge and technology, citing progress made under the sustainable development goals.","Climate agriculture":"Rob Jetten states that the Netherlands is committed to developing climate-smart agriculture and water management, making funding available for partnerships, and calls on all countries to adhere to climate transition ambitions.","UN leadership":"Rob Jetten expresses gratitude to Secretary General Gutierrez for his service and notes the ongoing work of UN personnel."},"claims":[{"t":36,"quote":"Frank was a teenage girl without power or influence, but she had a pen and a diary.","topic":"WWII history","kind":"fact"},{"t":44,"quote":"A diary that would would make its way into the world and inspire millions of people.","topic":"WWII history","kind":"fact"},{"t":96,"quote":"The realization that doing nothing had led to the darkest chapters in human history.","topic":"Middle East conflict","kind":"fact"},{"t":128,"quote":"We see the unending human suffering in Gaza, Sudan, and so many other places in the world.","topic":"Middle East conflict","kind":"fact"},{"t":135,"quote":"We see violations of international law and of human rights which are in stark contrast to the UN's aims.","topic":"International law","kind":"fact"},{"t":229,"quote":"It is time that countries in Africa, Asia and Latin America at a fullyfledged place not only on the equal earth map but in the real world too.","topic":"UN reform","kind":"fact"},{"t":283,"quote":"take the attempts we've seen to undermine the international criminal court, which is based in my country, in my city.","topic":"International justice","kind":"fact"},{"t":300,"quote":"This court was established to protect us against impunity. This court was built on the foundations of the Nuremberg and Tokyo trials.","topic":"International justice","kind":"fact"},{"t":359,"quote":"we still need to fight impunity not least through the special tribunal for the crime of aggression against Ukraine which the Netherlands has offered to host in the H.","topic":"Ukraine war","kind":"fact"},{"t":396,"quote":"And since the downing of flight MH17, the Netherlands has come to understand this only too well.","topic":"Ukraine war","kind":"fact"},{"t":419,"quote":"That was the idea underpinning the establishment 80 years ago of the International Court of Justice, the principal judicial organ of the United Nations.","topic":"AI governance","kind":"fact"},{"t":434,"quote":"more and more countries are finding their way to the ICJ","topic":"AI governance","kind":"fact"},{"t":485,"quote":"Nowhere on earth is a planet warming faster than in Western Europe.","topic":"Climate change","kind":"fact"},{"t":491,"quote":"But in the Caribbean part of our kingdom, including the countries of Aruba, Kurasau, and St. Martin, the effects of climate change have already been felt for much longer","topic":"Climate change","kind":"fact"},{"t":512,"quote":"after the horrors experienced by Nepal and a long series of forced fires, the truth should be clear to everyone.","topic":"Climate change","kind":"fact"},{"t":551,"quote":"Last year, the electrical vehicle markets grew by 20%. Wind power capacity grew by 14% and solar power by more than 30%.","topic":"Energy transition","kind":"number"},{"t":562,"quote":"And this growth in renewable energy has exceeded even the most optimistic projections from 10 years ago.","topic":"Energy transition","kind":"fact"},{"t":591,"quote":"This event in Colombia was attended by 57 countries and together these countries account for onethird of global GDP, onethird of energy demand and 1/5if of supply.","topic":"Energy transition","kind":"number"},{"t":640,"quote":"Thanks to our joint efforts on the sustainable development goals, 92% of the world's population now has access to electricity.","topic":"Climate action","kind":"number"},{"t":649,"quote":"And since 2015, we have doubled the amount of renewable energy we generate.","topic":"Climate action","kind":"number"},{"t":673,"quote":"For decades, the Netherlands has been working with partners around the world to develop climate smart agriculture and futureproof water management solutions.","topic":"Climate agriculture","kind":"fact"},{"t":708,"quote":"So we are once again making funding available for this purpose","topic":"Climate agriculture","kind":"fact"},{"t":793,"quote":"as we speak, more than 150,000 men and women are serving under the blue flag, giving vaccinations, providing food aid, and serving in peace missions.","topic":"UN leadership","kind":"number"},{"t":830,"quote":"Liberation from tyranny of unbridled nationalism, racism and fascism came too late for Anne Frank and many others in my country.","topic":"WWII history","kind":"fact"},{"t":841,"quote":"When it did finally come, it was brought by American, Canadian, British, Polish and other allied soldiers, many of them not much older than Anne Frank.","topic":"WWII history","kind":"fact"}],"promises":[{"t":708,"quote":"So we are once again making funding available for this purpose","topic":"Climate agriculture","kind":"promise"}],"attacks":[{"t":380,"quote":"Russia makes a choice every day to wage war. And Russia must be held to account for its flagrant violations of the UN charter, for the immeasurable suffering inflicted on so many victims and families in this senseless war.","topic":"Ukraine war","target":"Russia"}],"greece":[],"said":[],"pickup":[],"transcript":[{"t":2,"topic":"WWII history","text":"The assembly will now hear an address by his excellency Rob Yetan, Prime Minister and Minister for General Affairs of the Kingdom of the Netherlands. I request protocol to escort his excellency and invite him to Andreas the Mr. Presidents, your excellencies, ladies and gentlemen, and Frank was a teenage girl without power or influence, but she had a pen and a diary. A diary that would would make its way into the world and inspire millions of people. And I think that one of the reasons people are so inspired by an is that she had an unshakable belief in the power of people to turn the tide so that good prevails. She wrote and I quote, \"How wonderful it is that nobody needs to wait a single moment before starting to improve the world.\" And these words are just as powerful and true today."},{"t":74,"topic":"Middle East conflict","text":"This week is the perfect example of that. And I realize that the United Nations does not carry the most positive associations for everyone. And indeed, there is much that can and must be improved. But let us not forget what lay behind the founding of the United Nations over 80 years ago. The realization that doing nothing had led to the darkest chapters in human history. And we now live in a different time. New generations have arisen. and we face new challenges. But when we look at the world today, we see similar challenges as which preceded the founding of the United Nations. We see that the international legal order is under pressure in more and more places even though it is a very foundation to our freedom and We see the unending human suffering in Gaza, Sudan, and so many other places in the world."},{"t":135,"topic":"International law","text":"We see violations of international law and of human rights which are in stark contrast to the UN's aims. And we see institutions being undermined, institutions that were established to protect people and And we must not be naive about the causes. These constant threats and attempts to dismantle the legal order are fueled by people and groups with their own agenda. an agenda that runs counter to the interest of everyone else. Yes, everyone. And even those who don't feel directly threatened because they think it doesn't affect them. Sooner or later, everyone is affected as we saw in the time before the United Nations. And when major powers chose to pursue only their own interest, it is tempting to respond defensively. But as Mahatma Gandhi thought, an eye for an eye will only make the whole world blind."},{"t":202,"topic":"UN reform","text":"And so it is time for us, the global community, to choose to pursue the common interest, not by trying to build an entirely new world order, but simply by working together. and the middle powers must take the lead in fostering such international cooperation and everyone must be able to participate including those countries who are currently too often left on the sidelines. It is time that countries in Africa, Asia and Latin America at a fullyfledged place not only on the equal earth map but in the real world too. to start with here in the UN improved African representation in the security council at the very least if we want if we want to preserve the UN for the future we must change the balance of power in line with the changing times and modernize our institutions and it this means that we must focus on core tasks and stable finance financing, but also that we must work to protect the multilateral order with all our strength."},{"t":278,"topic":"International justice","text":"And because international law either works for everyone or for no one, take the attempts we've seen to undermine the international criminal court, which is based in my country, in my city. This undermines the international legal order as a whole, and that affects us all. This court was established to protect us against impunity. This court was built on the foundations of the Nuremberg and Tokyo trials. In the words of the Nuremberg chief prosecutor Robert H. Jackson, and I quote, \"One of the greatest tributes that power has ever paid to reason.\" And now with the ICC under attack, the writing is truly on the wall. After all, how can you possibly be opposed to prosecuting the very worst crimes? And I believe there can be only one response to say hands off the ICC and all those other institutions that protect the international legal order."},{"t":356,"topic":"Ukraine war","text":"Because the reality the reality is that we still need to fight impunity not least through the special tribunal for the crime of aggression against Ukraine which the Netherlands has offered to host in the H. And let me be absolutely clear. We cannot accept impunity in this fight. Ukraine has no choice but to defend itself. But Russia makes a choice every day to wage war. And Russia must be held to account for its flagrant violations of the UN charter, for the immeasurable suffering inflicted on so many victims and families in this senseless war. And since the downing of flight MH17, the Netherlands has come to understand this only too well. And many other others understand it too, with Russia threatening global food security and millions of people experiencing the And history teaches us that the only way to resolve conflict is through justice."},{"t":419,"topic":"AI governance","text":"That was the idea underpinning the establishment 80 years ago of the International Court of Justice, the principal judicial organ of the United Nations. And it's a conviction that is widely shared as illustrated by the fact that more and more countries are finding their way to the ICJ. So let us all continue to stand up for what we have built and strengthen it further as we go forward. Ladies and gentlemen, cooperation is the cornerstone of our history and cooperation is what the world expects of us now and in the future. Take the question of how we handle AI. We face a choice. Do we let a small group of companies and countries take all the decisions while the rest of us simply look on? or do we decide together within the logical setting of the United Nations what our future should look like? And it is also time for us to press forward together and tackle that other great challenge of our time, climate change."},{"t":485,"topic":"Climate change","text":"Nowhere on earth is a planet warming faster than in Western Europe. But in the Caribbean part of our kingdom, including the countries of Aruba, Kurasau, and St. Martin, the effects of climate change have already been felt for much longer and the same is true for many of your countries. For too long, the consequences of climate change have been trivialized or simply denied. But after the horrors experienced by Nepal and a long series of forced fires, the truth should be clear to everyone. The climate crisis will not just disappear if we pretend it doesn't exist. We are living on bored time and the generations that come after us will pay the price. And if you want to prevail that, prevent that, we must commit now to both mitigation and adaptation. And we all know what needs to be done. Countless reports are agreed on that and we have all the technology we need."},{"t":548,"topic":"Energy transition","text":"And fortunately, we are making progress. Last year, the electrical vehicle markets grew by 20%. Wind power capacity grew by 14% and solar power by more than 30%. And this growth in renewable energy has exceeded even the most optimistic projections from 10 years ago. And the challenge now is to accelerate this transition in all sectors and all parts of the world. and at the same time to reduce carbon emissions and phase out fossil fuels. That is why the Netherlands jointly with Colombia organized the world's first conference on transitioning away from fossil fuels. This event in Colombia was attended by 57 countries and together these countries account for onethird of global GDP, onethird of energy demand and 1/5if of supply. And together we worked to find concrete and practical solutions to take the transition forward."},{"t":611,"topic":"Climate action","text":"But climate action requires everyone to contribute. In November, we will gather at the COP in Turkey. And I know that many of you don't have high expectations. But in my view, this can only be explained by the pessimistic idea that we are somehow powerless. But that is not true. We have the knowledge and we have the technology to combat climate change and a better world is really within reach. Thanks to our joint efforts on the sustainable development goals, 92% of the world's population now has access to electricity. And since 2015, we have doubled the amount of renewable energy we generate. Child mortality has dropped sharply too because of this access. So climate action can be a catalyst for everyone to work together on solutions that concern us all. And we don't need to reinvent the wheel. A lot of good things are happening already."},{"t":673,"topic":"Climate agriculture","text":"For decades, the Netherlands has been working with partners around the world to develop climate smart agriculture and futureproof water management solutions. and we are keen to share our knowledge and knowow and we want to learn from what other countries are doing. There are so many great initiatives on the way but I also know there's much more to be done. The need to accelerate and scale up our efforts is only too clear and that demands our common commitment. The Netherlands wants to build practical partnerships with other countries. So we are once again making funding available for this purpose and at the same time we need to adapt to climate shocks that can no longer be avoided. These adaptations will require major investments both public and private because here too we cannot do it alone. Today I call on all countries to stick to these ambitions because one way or another a climate transition is coming."},{"t":739,"topic":"UN leadership","text":"But we can decide how it unfold. It can be chaotic or it can be carefully planned with an inclusive approach and economic benefits for all. Ladies and gentlemen, as I come to the end of my remarks, I have an even stronger sense of what Anne Frank was telling us because what she wrote is true. We have everything we need to change the world for the better. And we don't have to wait another minute. We aren't starting from scratch. We have already come a long way. And the journey will continue under the leadership of a new secretary general. Secretary General Gutierrez, thank you for all your years of hard work. You're leaving the United Nations at a turbulent moment, but we can all take pride in the fact that as we speak, more than 150,000 men and women are serving under the blue flag, giving vaccinations, providing food aid, and serving in peace missions."},{"t":806,"topic":"WWII history","text":"Even in this difficult times when darkness seems to be descending in many places on the high ideals of the United Nations. But the light has not gone out. The torch of peace and justice still flickers and guides us just as it did in my country more than 80 years ago. Liberation from tyranny of unbridled nationalism, racism and fascism came too late for Anne Frank and many others in my country. When it did finally come, it was brought by American, Canadian, British, Polish and other allied soldiers, many of them not much older than Anne Frank. And among their many resting places far from their homes, is an American cemetery in Marata, a small village in the south of the Netherlands. A wall stands swatch over their graves, and it is inscribed a simple epithes we throw the torch be yours to hold it high."},{"t":882,"topic":null,"text":"Let us pledge as a new generation to always hold it high. Thank you very On behalf of the assembly, I wish to thank the Prime Minister and Minister for General Affairs of the Kingdom of the Netherlands."}],"compare":[{"topic":"Climate Change","share":0.3517,"mean":0.0412,"rank":1,"others":77},{"topic":"UN & its reform","share":0.1991,"mean":0.2048,"rank":94,"others":170},{"topic":"International Law & Order","share":0.1863,"mean":0.0597,"rank":18,"others":102},{"topic":"Artificial Intelligence","share":0.0916,"mean":0.0503,"rank":41,"others":83},{"topic":"Russia-Ukraine War","share":0.0869,"mean":0.035,"rank":27,"others":44},{"topic":"Middle East","share":0.0845,"mean":0.0069,"rank":6,"others":19}]};
